import { useState } from "react";
import Login from "./pages/Login";

function App() {
  const [user, setUser] = useState(null);

  // Esta función se llama cuando el login es exitoso.
  const handleLogin = (userData) => {
    setUser(userData); // Guarda el usuario en el estado (más adelante puedes guardar en contexto)
  };

  if (!user) {
    // Si no hay usuario autenticado, muestra el login
    return <Login onLogin={handleLogin} />;
  }

  // Aquí puedes mostrar el dashboard o panel principal
  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-blue-500">

      <h1 className="text-4xl font-bold mb-4">Bienvenido, {user.nombre || user.email}!</h1>
      <button
        className="px-4 py-2 bg-red-500 text-white rounded font-bold"
        onClick={() => {
          localStorage.removeItem("token");
          setUser(null);
        }}
      >
        Cerrar sesión
      </button>
    </div>
  );
}

export default App;
